  if (dipped && !oscillate) lines.push('Blue blobs dipped first and red blobs faded later.')
  else if (lagTicks != null && redPeaks.length >= 1 && bluePeaks.length >= 1) {
    lines.push('Blue blobs grew first, then red blobs followed.')
  }
