pnpm exec tsx -e '
import { createWorld, stepWorld } from "./src/sim/engine.ts";
import { PRESETS } from "./src/sim/presets.ts";
import { summarize } from "./src/sim/summary.ts";
const blocks = "▁▂▃▄▅▆▇█";
function spark(values, width=64) {
  const buckets=[];
  for (let i=0;i<width;i++){
    const s=Math.floor(i*values.length/width), e=Math.max(s+1,Math.floor((i+1)*values.length/width));
    let m=0; for (let j=s;j<e;j++) m=Math.max(m, values[j]); buckets.push(m);
  }
  const max=Math.max(...buckets,1);
  return buckets.map(v=>blocks[Math.min(7,Math.floor(v/max*7.999))]).join("");
}
for (const preset of PRESETS) {
  for (const seed of preset.id==="balanced" ? [7,3,11,21] : [preset.params.seed]) {
    const w = createWorld({...preset.params, seed});
    for (let i=0;i<12000;i++) stepWorld(w);
    const b=w.history.map(s=>s.blue), r=w.history.map(s=>s.red), f=w.history.map(s=>s.fruit);
    const story=summarize(w.history);
    console.log("\n"+preset.id+"#"+seed, "cap", w.hitCap, "end", b.at(-1), r.at(-1), "max", Math.max(...b), Math.max(...r), "meanB", (b.reduce((s,v)=>s+v,0)/b.length).toFixed(1));
    console.log("B", spark(b));
    console.log("R", spark(r));
    console.log("F", spark(f));
    console.log(story.lines.join(" | "));
  }
}
'

