import { createWorld, stepWorld } from "./src/sim/engine.ts";
import { PRESETS } from "./src/sim/presets.ts";
const base = PRESETS[0].params;
function stats(params) {
  const w = createWorld(params);
  for (let i=0;i<7000;i++) stepWorld(w);
  const b=w.history.map(s=>s.blue), r=w.history.map(s=>s.red);
  const bMax=Math.max(...b), rMax=Math.max(...r);
  const peakAt=b.indexOf(bMax);
  const after=b.slice(peakAt);
  const bMin=Math.min(...after);
  const minAt=peakAt+after.indexOf(bMin);
  return {bEnd:b.at(-1), rEnd:r.at(-1), bMax, rMax, bMin, minAt, peakAt, bornB:w.bornBlue, bornR:w.bornRed, cap:w.hitCap};
}
const contacts=[8,12,16];
const uses=[1.1,1.45];
const copies=[120,150];
const pauses=[28,48];
for (const redContact of contacts) for (const redEnergyUse of uses) for (const redCopy of copies) for (const redPause of pauses) {
  const s=stats({...base, redContact, redEnergyUse, redCopy, redPause, startRed:2, blueCopy:70, fruitLimit:6});
