args.command:
pnpm exec tsx -e '
import { createWorld, stepWorld } from "./src/sim/engine.ts";
import { PRESETS } from "./src/sim/presets.ts";
import { summarize } from "./src/sim/summary.ts";
const base = {...PRESETS[0].params, fruitLimit:6, blueCopy:70, startRed:2};
const configs = [
  {name:"A", redContact:12, redEnergyUse:1.45, redCopy:150, redPause:48},
  {name:"B", redContact:12, redEnergyUse:1.1, redCopy:120, redPause:48},
  {name:"C", redContact:8, redEnergyUse:1.45, redCopy:120, redPause:48},
];
const blocks="▁▂▃▄▅▆▇█";
function spark(values,width=64){const buckets=[];for(let i=0;i<width;i++){const s=Math.floor(i*values.length/width),e=Math.max(s+1,Math.floor((i+1)*values.length/width));let m=0;for(let j=s;j<e;j++)m=Math.max(m,values[j]||0);buckets.push(m);}const max=Math.max(...buckets,1);return buckets.map(v=>blocks[Math.min(7,Math.floor(v/max*7.999))]).join("");}
for (const cfg of configs) {
  let lived=0;
  for (const seed of [7,3,11,21,42]) {
    const w=createWorld({...base, ...cfg, seed});
    for (let i=0;i<12000;i++) stepWorld(w);
    const b=w.history.map(s=>s.blue), r=w.history.map(s=>s.red);
    const alive=b.at(-1)>0 && r.at(-1)>0; if(alive) lived++;
    console.log(cfg.name, seed, "end", b.at(-1), r.at(-1), "max", Math.max(...b), Math.max(...r), alive?"LIVE":"DEAD");
    console.log("B", spark(b));
    console.log("R", spark(r));
    console.log(summarize(w.history).lines.join(" | "));
  }
  console.log(cfg.name, "lived", lived, "/5\n");
}
'

