  const t1 = Math.max(t0 + 1, history[history.length - 1]?.tick ?? 1)
  ctx.beginPath()
  values.forEach((value, index) => {
    const x = pad.l + ((history[index].tick - t0) / (t1 - t0)) * (w - pad.l - pad.r)
    const y = pad.t + (1 - (value - min) / (max - min || 1)) * (h - pad.t - pad.b)
