    else ctx.lineTo(x, y)
  })
  ctx.strokeStyle = color
  ctx.lineWidth = 2
  ctx.stroke()
}

function strokeNullable(
  ctx: CanvasRenderingContext2D,
  values: (number | null)[],
  history: Sample[],
  color: string,
  min: number,
  max: number,
  w: number,
  h: number,
  pad: { l: number; r: number; t: number; b: number },
) {
  if (history.length < 2) return
  const t0 = history[0].tick
  const t1 = Math.max(t0 + 1, history[history.length - 1].tick)
  let drawing = false
  ctx.beginPath()
  values.forEach((value, index) => {
    if (value == null) {
      drawing = false
      return
    }
    const x = pad.l + ((history[index].tick - t0) / (t1 - t0)) * (w - pad.l - pad.r)
    const y = pad.t + (1 - (value - min) / (max - min || 1)) * (h - pad.t - pad.b)
    if (!drawing) {
      ctx.moveTo(x, y)
      drawing = true
    } else ctx.lineTo(x, y)
  })
  ctx.strokeStyle = color
  ctx.lineWidth = 1.6
  ctx.stroke()
}

function roundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  ctx.beginPath()
  ctx.moveTo(x + r, y)
  ctx.arcTo(x + w, y, x + w, y + h, r)
  ctx.arcTo(x + w, y + h, x, y + h, r)
  ctx.arcTo(x, y + h, x, y, r)
  ctx.arcTo(x, y, x + w, y, r)
  ctx.closePath()
}

