  const eatWorld = createWorld({
    ...base,
    startTrees: 1,
    startBlue: 1,
    startRed: 0,
    fruitLimit: 3,
    blueCopy: 400,
    blueVision: 12,
    seed: 3,
    worldSize: 8,
