import puppeteer from 'puppeteer-core'

const chrome = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
const browser = await puppeteer.launch({
  executablePath: chrome,
  headless: true,
  args: ['--use-gl=angle', '--enable-webgl', '--ignore-gpu-blocklist'],
})
const page = await browser.newPage()
await page.setViewport({ width: 1440, height: 900 })
const errors: string[] = []
page.on('pageerror', (error) => errors.push(String(error)))
page.on('console', (message) => {
  if (message.type() === 'error') errors.push(message.text())
})
await page.goto('http://127.0.0.1:9352/', { waitUntil: 'networkidle0' })
const title = await page.title()
const h1 = await page.$eval('h1', (node) => node.textContent?.trim())
if (title !== 'Grok 4.7') throw new Error(`title ${title}`)
if (h1 !== 'Grok 4.7') throw new Error(`h1 ${h1}`)
await page.waitForSelector('canvas')
const beat = async () => Number((await page.$eval('.beat', (node) => node.textContent ?? '')).replace(/\D/g, ''))
const start = await beat()
await new Promise((resolve) => setTimeout(resolve, 900))
const later = await beat()
if (later <= start) throw new Error(`beat did not advance ${start} -> ${later}`)
await page.screenshot({ path: 'shot-running.png' })
await page.click('button[aria-pressed="false"]')
const paused = await beat()
await new Promise((resolve) => setTimeout(resolve, 500))
const still = await beat()
if (still !== paused) throw new Error(`pause failed ${paused} -> ${still}`)
await page.click('button::-p-text(Step)')
await new Promise((resolve) => setTimeout(resolve, 250))
const stepped = await beat()
if (stepped <= still) throw new Error(`step failed ${still} -> ${stepped}`)
await page.click('button::-p-text(Fruit-rich garden)')
await page.waitForFunction(() => document.body.textContent?.includes('Food comes back fast'))
await page.click('button::-p-text(Low-fruit garden)')
await page.waitForFunction(() => document.body.textContent?.includes('Scarce fruit'))
await page.click('button::-p-text(Red-heavy garden)')
await page.waitForFunction(() => document.body.textContent?.includes('under pressure'))
await page.click('button::-p-text(Play)')
await new Promise((resolve) => setTimeout(resolve, 700))
const canvas = await page.$('canvas')
const box = await canvas!.boundingBox()
if (!box) throw new Error('no canvas box')
await page.mouse.move(box.x + box.width * 0.62, box.y + box.height * 0.48)
await page.mouse.down()
await page.mouse.move(box.x + box.width * 0.38, box.y + box.height * 0.58, { steps: 8 })
await page.mouse.up()
await page.screenshot({ path: 'shot-dragged.png' })
await page.mouse.click(box.x + box.width * 0.5, box.y + box.height * 0.46)
await new Promise((resolve) => setTimeout(resolve, 200))
const inspector = await page.$eval('.inspector', (node) => node.textContent ?? '')
await page.screenshot({ path: 'shot-click.png' })
if (errors.length) throw new Error(errors.join('\n'))
console.log('ok', { title, h1, start, later, paused, stepped, inspector: inspector.slice(0, 180) })
await browser.close()

