success.beforeFullFileContent:
:root {
  color: #1d2b24;
  background:
    radial-gradient(900px 480px at 12% -10%, #fff8ec 0%, transparent 55%),
    radial-gradient(800px 500px at 110% 0%, #d7ecda 0%, transparent 46%),
    #e7efe4;
  font-family: "Avenir Next", "Century Gothic", "Trebuchet MS", sans-serif;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
}

button, input { font: inherit; color: inherit; }

button {
  border: 0;
  background: #fffdf8;
  border-radius: 999px;
  padding: 8px 14px;
  box-shadow: inset 0 0 0 1px rgba(36, 64, 46, 0.14);
  cursor: pointer;
}

button:hover { background: #fff; }

button[aria-pressed='true'] {
  background: #214232;
  color: #f4fff6;
  box-shadow: none;
}

button.alert {
  background: #ffe7c2;
}

h1, h2, legend {
  font-family: "Iowan Old Style", Palatino, Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.03em;
}

h1 {
  margin: 0;
  font-size: 1.7rem;
}

h2 {
  margin: 14px 0 6px;
  font-size: 1.05rem;
}

.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr) 360px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas:
    "top top top"
    "controls stage side";
  gap: 12px;
  padding: 12px;
}

.top {
  grid-area: top;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.transport {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.beat {
  font-variant-numeric: tabular-nums;
  color: #5c6b62;
  padding-left: 6px;
}

.controls {
  grid-area: controls;
  overflow: auto;
  min-height: 0;
  padding-right: 4px;
}

.stage {
  grid-area: stage;
  position: relative;
  min-width: 0;
  min-height: 0;
  border-radius: 28px;
  overflow: hidden;
  background:
    radial-gradient(420px 220px at 50% 38%, rgba(255, 252, 245, 0.55), transparent 70%),
    linear-gradient(180deg, #e7f2e4, #d5e4d4);
  box-shadow: 0 18px 50px rgba(40, 70, 48, 0.12);
}

.stage canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

.side {
  grid-area: side;
  overflow: auto;
  min-height: 0;
  padding-right: 2px;
}

.hud, .stage-hint, .actions {
  position: absolute;
  z-index: 2;
  pointer-events: none;
}

.hud {
  top: 14px;
  left: 14px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.hud span, .paused {
  background: rgba(255, 252, 247, 0.88);
  border-radius: 999px;
  padding: 6px 10px;
  box-shadow: 0 6px 18px rgba(40, 60, 40, 0.08);
  font-variant-numeric: tabular-nums;
}

.hud small { color: #5c6b62; margin-left: 4px; }

.stage-hint {
  left: 14px;
  bottom: 14px;
  margin: 0;
  color: #3d5246;
  background: rgba(255, 252, 247, 0.78);
  border-radius: 999px;
  padding: 6px 10px;
}

.actions {
  right: 14px;
  bottom: 14px;
  margin: 0;
  max-width: 46%;
  text-align: right;
  color: #3d5246;
  background: rgba(255, 252, 247, 0.78);
  border-radius: 16px;
  padding: 6px 10px;
}

.swatch {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  border-radius: 999px;
  margin-right: 4px;
  vertical-align: -1px;
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.12);
}

.swatch.fruit { background: #7ed35a; }
.swatch.blue, .inspector.blue .swatch { background: #3c92f5; }
.swatch.red, .inspector.red .swatch { background: #ef4d5d; }

.presets { display: flex; flex-wrap: wrap; gap: 6px; }

.preset { padding: 7px 10px; font-size: 0.86rem; }

.blurb, .group p, .axis, .story, .inspector p, .lifetime {
  color: #5c6b62;
  font-size: 0.86rem;
  line-height: 1.35;
}

.group {
  margin: 10px 0 0;
  padding: 8px 10px 10px;
  border: 0;
  border-radius: 16px;
  background: rgba(255, 252, 247, 0.76);
  box-shadow: inset 3px 0 0 #c5b49a;
}

.group.fruit { box-shadow: inset 3px 0 0 #2f9e44; }
.group.blue { box-shadow: inset 3px 0 0 #2f78f0; }
.group.red { box-shadow: inset 3px 0 0 #ef3d55; }

.group legend { padding: 0 4px; }

.slider { display: grid; gap: 2px; margin: 8px 0; font-size: 0.82rem; }
.slider span { display: flex; justify-content: space-between; gap: 8px; }
.slider strong { font-variant-numeric: tabular-nums; }
.slider input[type='range'] { width: 100%; accent-color: #2f6b45; }
.group.blue input[type='range'] { accent-color: #2f78f0; }
.group.red input[type='range'] { accent-color: #ef3d55; }
.group.fruit input[type='range'] { accent-color: #2f9e44; }
.slider input[type='number'] {
  width: 100%;
  border: 0;
  border-radius: 8px;
  padding: 6px 8px;
  background: #fff;
  box-shadow: inset 0 0 0 1px rgba(36, 64, 46, 0.12);
}

.dirty { color: #8a5a12; margin-bottom: 0; }

.charts, .inspector, .lifetime {
  background: rgba(255, 252, 247, 0.8);
  border-radius: 18px;
  padding: 10px 12px 12px;
  margin-bottom: 10px;
}

.charts header, .legend, .scale, .trait-legend, .peaks {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

.charts header h2, .legend { margin: 0; }

.legend, .trait-legend { font-size: 0.8rem; margin: 6px 0; }
.muted { color: #8a7560; }

.chart {
  width: 100%;
  height: 168px;
  display: block;
}

.chart.phase { height: 150px; }
.chart.traits { height: 96px; }

.peaks { margin: 8px 0 0; }
.peaks div { min-width: 64px; }
.peaks dt { color: #8a7560; font-size: 0.72rem; }
.peaks dd { margin: 0; font-variant-numeric: tabular-nums; }

.inspector h2 { display: flex; align-items: center; gap: 6px; margin-top: 0; }
.inspector h2 span { color: #8a7560; font-family: "Avenir Next", sans-serif; font-size: 0.85rem; }
.gone { color: #8a4b32; }

.energy { display: flex; justify-content: space-between; font-size: 0.85rem; }
.bar {
  height: 8px;
  border-radius: 999px;
  background: #efe4d4;
  overflow: hidden;
  margin: 4px 0 8px;
}
.inspector.blue .bar span { background: #3c92f5; }
.inspector.red .bar span { background: #ef4d5d; }
.bar span { display: block; height: 100%; }

.inspector dl { margin: 0; display: grid; gap: 6px; }
.inspector dl div { display: grid; grid-template-columns: 92px 1fr; gap: 8px; font-size: 0.86rem; }
.inspector dt { color: #8a7560; }
.inspector dd { margin: 0; }
.inspector small { display: block; color: #8a7560; }

.story { margin: 4px 0; color: #1d2b24; }

@media (max-width: 1100px) {
  .app {
    height: auto;
    grid-template-columns: 1fr;
    grid-template-areas:
      "top"
      "stage"
      "side"
      "controls";
  }
  .stage { height: 72vh; min-height: 420px; }
}

