  align-items: center;
  flex-wrap: wrap;
}

.charts header h2, .legend { margin: 0; }

.legend, .trait-legend { font-size: 0.8rem; margin: 6px 0; }
.muted { color: #8a7560; }

.chart {
  width: 100%;
  height: 168px;
  display: block;
}

.chart.phase { height: 150px; }
.chart.traits { height: 96px; }

.peaks { margin: 8px 0 0; }
.peaks div { min-width: 64px; }
.peaks dt { color: #8a7560; font-size: 0.72rem; }
.peaks dd { margin: 0; font-variant-numeric: tabular-nums; }

.inspector h2 { display: flex; align-items: center; gap: 6px; margin-top: 0; }
.inspector h2 span { color: #8a7560; font-family: "Avenir Next", sans-serif; font-size: 0.85rem; }
.gone { color: #8a4b32; }

.energy { display: flex; justify-content: space-between; font-size: 0.85rem; }
.bar {
  height: 8px;
  border-radius: 999px;
  background: #efe4d4;
  overflow: hidden;
  margin: 4px 0 8px;
}
.inspector.blue .bar span { background: #3c92f5; }
.inspector.red .bar span { background: #ef4d5d; }
.bar span { display: block; height: 100%; }

.inspector dl { margin: 0; display: grid; gap: 6px; }
.inspector dl div { display: grid; grid-template-columns: 92px 1fr; gap: 8px; font-size: 0.86rem; }
.inspector dt { color: #8a7560; }
.inspector dd { margin: 0; }
.inspector small { display: block; color: #8a7560; }

.story { margin: 4px 0; color: #1d2b24; }

@media (max-width: 1100px) {
  .app {
    height: auto;
    grid-template-columns: 1fr;
    grid-template-areas:
      "top"
      "stage"
      "side"
      "controls";
  }
  .stage { height: 72vh; min-height: 420px; }
}

